interface Profile {
  nickname?: string;
}

function show(profile: Profile): string {
  // @ts-ignore
  const a = profile.nickname.toUpperCase();
  const b = profile.nickname!.toUpperCase();
  const c = (profile as { nickname: string }).nickname.toUpperCase();
  return a + b + c;
}

console.log(show({}));

